import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SecureFileAccess {
    // This code fixes the vulnerability by validating the path and ensuring it stays within the allowed directory.
    public String readFile(String filename) {
        // Construct the base directory path securely.
        Path baseDir = Paths.get("/var/data");

        // Resolve the full path from user input relative to the base directory.
        Path filePath = baseDir.resolve(filename).normalize();

        // Check if the resolved path is still within the intended base directory.
        if (!filePath.startsWith(baseDir)) {
            throw new SecurityException("Attempted path traversal detected.");
        }

        File file = filePath.toFile();

        if (file.exists()) {
            return "File found: " + file.getAbsolutePath();
        }
        return "File not found";
    }
}
